mapper.select:
select A.*, B.category, (select concat(F.upload_path, '/s_', F.file_name, '_', F.file_dname, F.file_ext) from `Auct_FileUpload` F where F.anum = A.anum order by F.fnum limit 1) as thumb from `Auct_Master` A left join `Auct_Category` B on A.cnum = B.cnum
where A.unum = #{unum}
inner join `Auct_Concern` C on A.anum = C.anum where C.unum = #{unum}
where (A.prod_name like concat('%', #{value}, '%') or B.category like concat('%', #{value}, '%'))
order by case when now() < A.auct_start then 1 when now() > A.auct_end then 2 else 0 end, A.auct_end, A.anum desc limit #{offset}, #{cntPerPage}

mapper.update:
update Auct_Master
set start_amt = #{bidAmt}, join_cnt = join_cnt + 1
where anum = #{anum} and start_amt = #{expectedAmt}
